# ── Extract default class info ────────────────────────────────────────────────
# We need: default ctrlrange per class, default joint axis per class

class_info = {}

def parse_defaults(node, inherited=None):
    """Recursively walk <default> elements and collect per-class info."""
    if inherited is None:
        inherited = {}
    for child in node:
        if child.tag == "default":
            cname = child.get("class", "__root__")
            info = dict(inherited)  # inherit from parent
            j = child.find("joint")
            g = child.find("general")
            if j is not None:
                if j.get("range"):  info["joint_range"] = j.get("range")
                if j.get("axis"):   info["joint_axis"]  = j.get("axis")
            if g is not None:
                if g.get("ctrlrange"): info["ctrl_range"] = g.get("ctrlrange")
            class_info[cname] = info
            parse_defaults(child, info)

# The top-level <default> has one child <default class="xarm7"> which has sub-defaults
