# ── Extract sites ─────────────────────────────────────────────────────────────
sites = []
for site in root.iter("site"):
    sname = site.get("name")
    if sname:
        sites.append(sname)
print("Sites:", sites)

# ── Body tree (leaf bodies) ───────────────────────────────────────────────────
def get_bodies(node, depth=0):
    for child in node:
        if child.tag == "body":
            bname = child.get("name")
            children_bodies = [c for c in child if c.tag == "body"]
            is_leaf = len(children_bodies) == 0
            print("  " * depth + f"{'[LEAF] ' if is_leaf else ''}{bname}")
            get_bodies(child, depth + 1)

wb = root.find("worldbody")
print("\nBody tree:")
get_bodies(wb)

# ── Free-joint bodies (graspable) ─────────────────────────────────────────────
graspable = []
for body in root.iter("body"):
    for jnt in body:
        if jnt.tag == "joint" and jnt.get("type") == "free":
            graspable.append(body.get("name"))
print("\nGraspable (free-joint) bodies:", graspable)

